tool.parameters:
{
  "type": "object",
  "properties": {
    "city": {
      "type": "string",
      "description": "City in English or Russian, e.g. Москва. Popular Russian city aliases are normalized to English."
    },
    "keywords": {
      "type": "string",
      "description": "Plain-text English search phrase (GDELT searches English translations). No GDELT operators."
    },
    "timespan": {
      "type": "string",
      "description": "Publication lookback: integer + min, h, d, w or m; default 24h. Minimum 15min; maximum 3 months. Ignored with absolute dates."
    },
    "start_date": {
      "type": "string",
      "description": "Optional UTC ISO 8601 start timestamp ending in Z, within the last 3 months. If omitted with end_date, uses the start of the available window."
    },
    "end_date": {
      "type": "string",
      "description": "Optional UTC ISO 8601 end timestamp ending in Z. Cannot be in the future. If omitted with start_date, uses now. Minimum interval 15 minutes."
    },
    "source_language": {
      "type": "string",
      "description": "Original publication language: English name or GDELT three-letter code (e.g. russian, eng)."
    },
    "source_country": {
      "type": "string",
      "description": "Publisher country, NOT event country. English country name or two-letter FIPS code (not ISO)."
    },
    "sort": {
      "type": "string",
      "enum": [
        "datedesc",
        "hybridrel"
      ],
      "description": "Sort by newest first (default datedesc) or relevance."
    },
    "limit": {
      "type": "integer",
      "minimum": 1,
      "maximum": 50,
      "description": "Maximum article count, default 10."
    }
  },
  "required": [],
  "additionalProperties": false
}
